export const s12EconomicsHi: Record<string, { stem: string; options: string[]; explanation: string }> = {
  "s12eco-b-001": { stem: "गणनावाचक उपयोगिता विश्लेषण के अंतर्गत, दो वस्तुओं X और Y पर अपनी आय व्यय करने वाली उपभोक्ता संतुलन में होती है जब:", options: ["MUx = MUy", "MUx/Px = MUy/Py", "MUx × Px = MUy × Py", "Px = Py"], explanation: "सम-सीमांत उपयोगिता नियम के अनुसार प्रति रुपया सीमांत उपयोगिता सभी वस्तुओं में बराबर (और मुद्रा की सीमांत उपयोगिता के बराबर) होनी चाहिए। केवल MU बराबर होना कीमतों की उपेक्षा करता है।" },
  "s12eco-b-002": { stem: "एक उपभोक्ता केवल वस्तु X खरीदती है, जिसकी कीमत ₹5 प्रति इकाई है। उसके लिए एक रुपये की सीमांत उपयोगिता 4 यूटिल है। संतुलन पर, खरीदी गई X की अंतिम इकाई की सीमांत उपयोगिता है:", options: ["20 यूटिल", "1.25 यूटिल", "9 यूटिल", "4 यूटिल"], explanation: "एक वस्तु की स्थिति में संतुलन MUx/Px = MUm, अतः MUx = 4 × 5 = 20 यूटिल। 1.25 गलती से 5 को 4 से भाग देने पर आता है।" },
  "s12eco-b-003": { stem: "अनधिमान वक्र सामान्यतः मूल बिंदु की ओर उन्नतोदर होते हैं, इसका कारण है:", options: ["माँग का नियम", "बढ़ती सीमांत प्रतिस्थापन दर", "घटती सीमांत प्रतिस्थापन दर", "मुद्रा की स्थिर सीमांत उपयोगिता"], explanation: "जैसे-जैसे उपभोक्ता को X अधिक मिलता है, वह X की प्रत्येक अतिरिक्त इकाई के लिए Y की कम मात्रा छोड़ने को तैयार होता है, अतः MRS (ढाल) घटती है और वक्र मूल बिंदु की ओर झुकता है।" },
  "s12eco-b-004": { stem: "एक उपभोक्ता की आय ₹100 है। वस्तु X (क्षैतिज अक्ष पर) की कीमत ₹5 और वस्तु Y की कीमत ₹10 है। वह X की अधिकतम कितनी मात्रा खरीद सकती है तथा उसकी बजट रेखा की ढाल क्या है?", options: ["10 इकाई, −2", "20 इकाई, −2", "10 इकाई, −0.5", "20 इकाई, −0.5"], explanation: "अधिकतम X = 100/5 = 20 इकाई। बजट रेखा की ढाल −Px/Py = −5/10 = −0.5 है।" },
  "s12eco-b-005": { stem: "किसी वस्तु की कीमत ₹10 से घटकर ₹8 होने पर उसकी माँगी गई मात्रा 40 इकाई से बढ़कर 50 इकाई हो जाती है। प्रतिशत विधि (प्रारंभिक मानों) से माँग की कीमत लोच (निरपेक्ष मान) है:", options: ["0.8", "1.25", "2.5", "0.5"], explanation: "मात्रा में प्रतिशत परिवर्तन = 10/40 × 100 = 25%; कीमत में प्रतिशत परिवर्तन = 2/10 × 100 = 20%। लोच = 25/20 = 1.25।" },
  "s12eco-b-006": { stem: "यदि किसी वस्तु की कीमत घटने पर उस पर कुल व्यय अपरिवर्तित रहता है, तो उस वस्तु की माँग की कीमत लोच है:", options: ["शून्य (पूर्णतः बेलोचदार)", "इकाई से अधिक", "इकाई के बराबर", "इकाई से कम"], explanation: "कुल व्यय विधि के अनुसार कीमत परिवर्तन के बाद व्यय अपरिवर्तित रहने का अर्थ है कि मात्रा में आनुपातिक वृद्धि कीमत की कमी को ठीक-ठीक संतुलित करती है, अतः लोच इकाई है।" },
  "s12eco-b-007": { stem: "एक उपभोक्ता की आय बढ़ती है और अन्य बातें समान रहने पर किसी वस्तु के लिए उसकी माँग घट जाती है। यह वस्तु है:", options: ["सामान्य वस्तु", "विलासिता वस्तु", "पूरक वस्तु", "निम्नस्तरीय वस्तु"], explanation: "निम्नस्तरीय वस्तु की माँग आय के विपरीत दिशा में बदलती है। सामान्य वस्तुओं (विलासिता सहित) की माँग आय के साथ बढ़ती है।" },
  "s12eco-b-008": { stem: "अल्पकालीन उत्पादन फलन में परिवर्ती साधन का कुल उत्पाद (TP) अधिकतम होता है जब:", options: ["सीमांत उत्पाद शून्य हो", "सीमांत उत्पाद अधिकतम हो", "औसत उत्पाद सीमांत उत्पाद के बराबर हो", "औसत उत्पाद शून्य हो"], explanation: "जब तक MP धनात्मक है TP बढ़ता है और MP ऋणात्मक होने पर घटने लगता है; अतः TP वहाँ अधिकतम है जहाँ MP = 0। AP = MP पर AP अधिकतम होता है, TP नहीं।" },
  "s12eco-b-009": { stem: "परिवर्ती अनुपात के नियम के अंतर्गत एक विवेकशील उत्पादक द्वितीय अवस्था में कार्य करता है, जो स्थित है:", options: ["मूल बिंदु और उस बिंदु के बीच जहाँ MP अधिकतम है", "उस बिंदु जहाँ AP अधिकतम है और उस बिंदु जहाँ MP शून्य है, के बीच", "उस बिंदु जहाँ MP शून्य है और उस बिंदु जहाँ TP शून्य हो जाता है, के बीच", "उस बिंदु जहाँ MP अधिकतम है और उस बिंदु जहाँ AP अधिकतम है, के बीच"], explanation: "द्वितीय अवस्था (ह्रासमान प्रतिफल) वहाँ से आरंभ होती है जहाँ AP अधिकतम (AP = MP) है और वहाँ समाप्त होती है जहाँ MP = 0 (TP अधिकतम) है। प्रथम अवस्था में स्थिर साधन का अल्प-उपयोग होता है और तृतीय अवस्था में MP ऋणात्मक होता है।" },
  "s12eco-b-010": { stem: "एक फर्म की कुल स्थिर लागत ₹200 है। 10 इकाई उत्पादन पर उसकी कुल परिवर्ती लागत ₹300 है। इस उत्पादन पर उसकी औसत लागत है:", options: ["₹20", "₹30", "₹500", "₹50"], explanation: "TC = 200 + 300 = ₹500, अतः AC = 500/10 = ₹50। ₹30 AVC है और ₹20 AFC है।" },
  "s12eco-b-011": { stem: "सीमांत लागत (MC) वक्र U-आकार के औसत लागत (AC) वक्र को काटता है:", options: ["AC के अधिकतम बिंदु पर", "AC के न्यूनतम बिंदु पर", "AFC के न्यूनतम बिंदु पर", "AC के गिरते भाग के किसी भी बिंदु पर"], explanation: "जब MC, AC से नीचे होता है तो AC घटता है; जब MC, AC से ऊपर होता है तो AC बढ़ता है। अतः MC, AC को उसके न्यूनतम बिंदु पर नीचे से काटता है।" },
  "s12eco-b-012": { stem: "औसत स्थिर लागत (AFC) वक्र का आकार होता है:", options: ["U-आकार का वक्र", "क्षैतिज सीधी रेखा", "आयताकार अतिपरवलय", "ऊपर की ओर ढलान वाली सीधी रेखा"], explanation: "AFC = TFC/Q, और AFC × Q = TFC स्थिर है, जो आयताकार अतिपरवलय का गुण है। यह निरंतर घटता है पर किसी अक्ष को नहीं छूता।" },
  "s12eco-b-013": { stem: "पूर्ण प्रतिस्पर्धा के अंतर्गत एक व्यक्तिगत फर्म के सामने माँग वक्र होता है:", options: ["बाजार कीमत पर पूर्णतः लोचदार (क्षैतिज)", "नीचे की ओर ढलान वाला", "पूर्णतः बेलोचदार (ऊर्ध्वाधर)", "ऊपर की ओर ढलान वाला"], explanation: "पूर्ण प्रतिस्पर्धी फर्म कीमत स्वीकारक होती है: वह उद्योग द्वारा निर्धारित कीमत पर कितनी भी मात्रा बेच सकती है, अतः उसका माँग (AR = MR) वक्र क्षैतिज होता है।" },
  "s12eco-b-014": { stem: "सीधी रेखा वाले, नीचे की ओर ढलान वाले माँग वक्र का सामना करने वाले एकाधिकारी के लिए सीमांत संप्राप्ति उस बिंदु पर शून्य होती है जहाँ माँग की कीमत लोच बराबर हो:", options: ["शून्य के", "अनंत के", "इकाई से अधिक के", "इकाई के"], explanation: "MR = P(1 − 1/e)। e = 1 होने पर MR = 0, अर्थात रैखिक माँग वक्र के मध्य बिंदु पर, जहाँ कुल संप्राप्ति अधिकतम होती है।" },
  "s12eco-b-015": { stem: "किसी वस्तु के बाजार माँग और पूर्ति फलन Qd = 100 − 2P तथा Qs = 40 + 4P हैं। संतुलन कीमत और मात्रा हैं:", options: ["P = ₹10, Q = 80", "P = ₹15, Q = 70", "P = ₹6, Q = 88", "P = ₹10, Q = 60"], explanation: "Qd = Qs रखने पर: 100 − 2P = 40 + 4P, अतः 6P = 60 और P = ₹10। तब Q = 100 − 20 = 80 (जाँच: 40 + 40 = 80)।" },
  "s12eco-b-016": { stem: "एक अर्थव्यवस्था के लिए बाजार कीमत पर GDP = ₹1,000 करोड़, विदेशों से निवल साधन आय = −₹20 करोड़, मूल्यह्रास = ₹50 करोड़ और निवल अप्रत्यक्ष कर = ₹70 करोड़ है। साधन लागत पर NNP (राष्ट्रीय आय) है:", options: ["₹900 करोड़", "₹940 करोड़", "₹860 करोड़", "₹1,020 करोड़"], explanation: "NNPfc = GDPmp + NFIA − मूल्यह्रास − निवल अप्रत्यक्ष कर = 1,000 − 20 − 50 − 70 = ₹860 करोड़। ऋणात्मक NFIA को +20 जोड़ने पर गलत उत्तर ₹900 करोड़ आता है।" },
  "s12eco-b-017": { stem: "निम्नलिखित में से कौन-सा राष्ट्रीय आय के आकलन में सम्मिलित नहीं किया जाता?", options: ["सरकारी कर्मचारियों के वेतन", "सरकार द्वारा दी गई वृद्धावस्था पेंशन", "स्वामी द्वारा अधिवासित मकानों का आरोपित किराया", "स्व-लेखा हेतु स्थायी परिसंपत्तियों के उत्पादन का मूल्य"], explanation: "वृद्धावस्था पेंशन अंतरण भुगतान है: यह चालू उत्पादक सेवाओं का प्रतिफल नहीं है, अतः इसे बाहर रखा जाता है। आरोपित किराया और स्व-लेखा उत्पादन सम्मिलित होते हैं।" },
  "s12eco-b-018": { stem: "एक अर्थव्यवस्था का मौद्रिक (नाममात्र) GDP ₹500 करोड़ है और GDP अपस्फायक 125 है। इसका वास्तविक GDP है:", options: ["₹625 करोड़", "₹375 करोड़", "₹500 करोड़", "₹400 करोड़"], explanation: "वास्तविक GDP = मौद्रिक GDP × 100/अपस्फायक = 500 × 100/125 = ₹400 करोड़। 1.25 से गुणा करना (₹625 करोड़) सामान्य भूल है।" },
  "s12eco-b-019": { stem: "राष्ट्रीय आय के आकलन में दोहरी गणना की समस्या से बचा जाता है:", options: ["केवल मध्यवर्ती वस्तुओं की गणना करके", "मूल्यवर्धित विधि अपनाकर या केवल अंतिम वस्तुओं की गणना करके", "सभी अंतरण भुगतानों को सम्मिलित करके", "अर्थव्यवस्था की प्रत्येक बिक्री का मूल्य जोड़कर"], explanation: "अंतिम वस्तुओं में मध्यवर्ती वस्तुओं का मूल्य दोबारा गिनने से उत्पादन बढ़ा-चढ़ाकर आता है। प्रत्येक चरण का केवल मूल्यवर्धन (या केवल अंतिम वस्तुएँ) जोड़ने से यह समस्या दूर होती है।" },
  "s12eco-b-020": { stem: "वाणिज्यिक बैंकों को जमाओं का 20% आरक्षित रखना होता है। यदि ₹1,000 की प्रारंभिक (प्राथमिक) जमा की जाती है, तो बैंकिंग प्रणाली अधिकतम कुल कितनी जमाएँ सृजित कर सकती है?", options: ["₹5,000", "₹2,000", "₹200", "₹1,250"], explanation: "मुद्रा (साख) गुणक = 1/LRR = 1/0.2 = 5, अतः कुल जमाएँ = 1,000 × 5 = ₹5,000।" },
  "s12eco-b-021": { stem: "जब RBI तरलता संकट झेल रहे किसी वाणिज्यिक बैंक को, जो अन्य स्रोतों से उसे पूरा नहीं कर पा रहा, धन उपलब्ध कराता है, तब वह कार्य करता है:", options: ["विदेशी मुद्रा भंडार के संरक्षक के रूप में", "अंतिम ऋणदाता के रूप में", "चयनात्मक साख के नियंत्रक के रूप में", "सरकार के बैंकर के रूप में"], explanation: "अंतिम ऋणदाता के रूप में केंद्रीय बैंक अस्थायी तरलता संकट झेल रहे सक्षम बैंकों को सहायता देता है, जिससे जमाकर्ताओं का विश्वास बना रहता है।" },
  "s12eco-b-022": { stem: "निम्नलिखित में से कौन-सा साख नियंत्रण का गुणात्मक (चयनात्मक) उपकरण है?", options: ["बैंक दर", "खुले बाजार की क्रियाएँ", "नकद आरक्षित अनुपात", "सीमांत आवश्यकता (मार्जिन आवश्यकता)"], explanation: "मार्जिन आवश्यकता विशिष्ट उद्देश्यों के लिए साख को नियंत्रित करती है, इसलिए यह चयनात्मक है। बैंक दर, OMO और CRR साख की कुल मात्रा को प्रभावित करते हैं (मात्रात्मक उपकरण)।" },
  "s12eco-b-023": { stem: "जब RBI खुले बाजार में सरकारी प्रतिभूतियाँ बेचता है, तो अर्थव्यवस्था पर इसका प्रभाव है कि यह:", options: ["तरलता (मुद्रा पूर्ति) घटाता है", "मुद्रा पूर्ति बढ़ाता है", "मुद्रा पूर्ति को अपरिवर्तित रखता है", "स्वतः रेपो दर घटा देता है"], explanation: "क्रेता प्रतिभूतियों के लिए RBI को भुगतान करते हैं, अतः बैंकों के आरक्षित कोष घटते हैं और उनकी साख सृजन क्षमता कम हो जाती है, जिससे मुद्रा पूर्ति घटती है।" },
  "s12eco-b-024": { stem: "यदि सीमांत उपभोग प्रवृत्ति (MPC) 0.8 है, तो निवेश गुणक का मान है:", options: ["1.25", "4", "8", "5"], explanation: "k = 1/(1 − MPC) = 1/0.2 = 5। 1.25 तो 1/MPC है, जो सामान्य भूल है।" },
  "s12eco-b-025": { stem: "एक अर्थव्यवस्था का उपभोग फलन C = 100 + 0.75Y है। Y = ₹1,000 करोड़ आय पर बचत है:", options: ["₹150 करोड़", "₹250 करोड़", "₹850 करोड़", "₹100 करोड़"], explanation: "C = 100 + 0.75 × 1,000 = ₹850 करोड़, अतः S = Y − C = 1,000 − 850 = ₹150 करोड़। ₹250 करोड़ स्वायत्त उपभोग की उपेक्षा करता है।" },
  "s12eco-b-026": { stem: "सरकार का राजकोषीय घाटा परिभाषित किया जाता है:", options: ["कुल व्यय में से राजस्व प्राप्तियाँ घटाकर", "कुल व्यय में से उधार को छोड़कर कुल प्राप्तियाँ घटाकर", "राजस्व व्यय में से राजस्व प्राप्तियाँ घटाकर", "प्राथमिक घाटे में से ब्याज भुगतान घटाकर"], explanation: "राजकोषीय घाटा = कुल व्यय − (राजस्व प्राप्तियाँ + गैर-ऋण पूँजीगत प्राप्तियाँ), जो सरकार की उधार आवश्यकता के बराबर है। विकल्प C राजस्व घाटा है।" },
  "s12eco-b-027": { stem: "निम्नलिखित में से कौन-सी सरकार की पूँजीगत प्राप्ति है?", options: ["आयकर", "सार्वजनिक क्षेत्र के उपक्रमों से लाभांश", "विनिवेश से प्राप्त राशि", "GST संग्रह"], explanation: "विनिवेश सरकार की परिसंपत्तियाँ घटाता है, अतः इससे प्राप्त राशि पूँजीगत प्राप्ति है। कर और लाभांश न दायित्व उत्पन्न करते हैं न परिसंपत्ति घटाते हैं, अतः ये राजस्व प्राप्तियाँ हैं।" },
  "s12eco-b-028": { stem: "निम्नलिखित में से कौन-सा लेन-देन भारत के भुगतान संतुलन के पूँजी खाते में दर्ज होता है?", options: ["सॉफ़्टवेयर सेवाओं का निर्यात", "विदेश में कार्यरत भारतीय श्रमिकों द्वारा भेजी गई राशि", "भारत में प्रत्यक्ष विदेशी निवेश", "कच्चे तेल का आयात"], explanation: "FDI परिसंपत्तियों और दायित्वों को बदलता है, अतः यह पूँजी खाते में जाता है। सेवाएँ, प्रेषण (अंतरण) और वस्तु आयात चालू खाते की मदें हैं।" },
  "s12eco-b-029": { stem: "नम्य विनिमय दर प्रणाली में रुपया-डॉलर दर ₹70 प्रति $ से बदलकर ₹75 प्रति $ हो जाती है। यह दर्शाता है:", options: ["रुपये का अधिमूल्यन; भारतीय निर्यात विदेशों में महँगे होते हैं", "रुपये का मूल्यह्रास; आयात सस्ते होते हैं", "रुपये का मूल्यह्रास; भारतीय निर्यात विदेशी क्रेताओं के लिए सस्ते होते हैं", "रुपये का अधिमूल्यन; आयात महँगे होते हैं"], explanation: "अब प्रति डॉलर अधिक रुपये चाहिए, अतः रुपये का मूल्यह्रास हुआ है। प्रत्येक डॉलर से अधिक भारतीय वस्तुएँ खरीदी जा सकती हैं, इसलिए निर्यात सस्ते होते हैं जबकि आयात महँगे होते हैं।" },
  "s12eco-b-030": { stem: "दो-क्षेत्रीय अर्थव्यवस्था (केवल परिवार और फर्में) में समग्र माँग में सम्मिलित है:", options: ["C + I", "C + I + G", "C + I + G + (X − M)", "C + S"], explanation: "सरकार या विदेशी क्षेत्र के बिना AD नियोजित उपभोग और नियोजित निवेश का योग है। G और निवल निर्यात केवल तीन और चार क्षेत्रीय मॉडलों में आते हैं।" },
  "s12eco-b-031": { stem: "NCERT में वर्णित भारत की पंचवर्षीय योजनाओं (1951–1990) के चार व्यापक लक्ष्यों में से कौन-सा नहीं था?", options: ["संवृद्धि", "आधुनिकीकरण", "आत्मनिर्भरता", "निजीकरण"], explanation: "योजना के लक्ष्य संवृद्धि, आधुनिकीकरण, आत्मनिर्भरता और समानता थे। निजीकरण 1991 के सुधारों के साथ ही नीतिगत जोर बना।" },
  "s12eco-b-032": { stem: "हरित क्रांति के प्रथम चरण (लगभग 1960 के दशक के मध्य से 1970 के दशक के मध्य तक) में HYV बीजों का प्रयोग मुख्यतः सीमित था:", options: ["पंजाब, आंध्र प्रदेश और तमिलनाडु जैसे अधिक संपन्न राज्यों तक", "बिहार और ओडिशा जैसे पूर्वी राज्यों तक", "वर्षा-आधारित पहाड़ी राज्यों तक", "सभी राज्यों में समान रूप से"], explanation: "HYV बीजों को सुनिश्चित सिंचाई और आगतों की आवश्यकता थी, अतः वे पहले बेहतर संसाधन वाले राज्यों में फैले और मुख्यतः गेहूँ उगाने वाले क्षेत्रों को लाभ हुआ। व्यापक प्रसार दूसरे चरण में हुआ।" },
  "s12eco-b-033": { stem: "अपनी उपभोग आवश्यकताएँ पूरी करने के बाद किसानों द्वारा बाजार में बेचा गया कृषि उत्पादन का भाग कहलाता है:", options: ["बफर स्टॉक", "विपणित अधिशेष", "न्यूनतम समर्थन मूल्य", "अधिप्राप्ति"], explanation: "विपणित अधिशेष उत्पादन का वह भाग है जो किसान बेचते हैं। हरित क्रांति के दौरान विपणित अधिशेष बढ़ने से सरकार को बफर स्टॉक बनाने में सहायता मिली।" },
  "s12eco-b-034": { stem: "1956 के औद्योगिक नीति प्रस्ताव ने उद्योगों को कितनी श्रेणियों में वर्गीकृत किया?", options: ["चार", "दो", "पाँच", "तीन"], explanation: "इसने तीन श्रेणियाँ बनाईं: राज्य के अनन्य स्वामित्व वाले उद्योग, वे उद्योग जिनमें नई इकाइयाँ सामान्यतः राज्य निजी सहयोग से स्थापित करेगा, और शेष उद्योग जो निजी क्षेत्र पर छोड़े गए।" },
  "s12eco-b-035": { stem: "1991 में भारत के सामने आया आर्थिक संकट मुख्यतः था:", options: ["अत्यंत कम विदेशी मुद्रा भंडार के साथ भुगतान संतुलन संकट", "बैंकिंग प्रणाली का पतन", "फसल विफलता से उत्पन्न अकाल", "शेयर बाजार का पतन"], explanation: "विदेशी मुद्रा भंडार इतना घट गया था कि वह लगभग दो सप्ताह के आयात के लिए ही पर्याप्त था, और भारत को विदेशी ऋण दायित्व चुकाने में कठिनाई हो रही थी।" },
  "s12eco-b-036": { stem: "1991 की नई आर्थिक नीति में 'स्थिरीकरण उपाय' अल्पकालीन उपाय थे, जिनका मुख्य उद्देश्य था:", options: ["दीर्घकालीन कुशलता और अंतरराष्ट्रीय प्रतिस्पर्धा बढ़ाना", "सार्वजनिक क्षेत्र की इकाइयों का विनिवेश", "भुगतान संतुलन की कमजोरियों को सुधारना और मुद्रास्फीति पर नियंत्रण करना", "भूमि सुधार लागू करना"], explanation: "स्थिरीकरण उपायों का लक्ष्य पर्याप्त विदेशी मुद्रा भंडार बहाल करना और बढ़ती कीमतों को नियंत्रित करना था। संरचनात्मक सुधार उपाय कुशलता हेतु दीर्घकालीन उपाय थे।" },
  "s12eco-b-037": { stem: "निम्नलिखित में से कौन-सा मानव पूँजी निर्माण का स्रोत नहीं है?", options: ["स्वास्थ्य पर व्यय", "कार्यस्थल पर प्रशिक्षण", "बेहतर वेतन वाले रोजगार हेतु प्रवसन", "नई मशीनरी की खरीद"], explanation: "शिक्षा, स्वास्थ्य, कार्यस्थल पर प्रशिक्षण, प्रवसन और सूचना मानव पूँजी के स्रोत हैं। मशीनरी भौतिक पूँजी है।" },
  "s12eco-b-038": { stem: "NCERT में प्रयुक्त निर्धनों के वर्गीकरण में, जो लोग सदैव निर्धन रहते हैं और जो सामान्यतः निर्धन रहते हैं पर कभी-कभी थोड़ा अधिक धन पा लेते हैं, उन्हें मिलाकर कहा जाता है:", options: ["अल्पकालिक निर्धन", "चक्रीय निर्धन", "चिरकालिक निर्धन", "कभी-कभी निर्धन"], explanation: "चिरकालिक निर्धनों में सदैव निर्धन और सामान्यतः निर्धन आते हैं। चक्रीय निर्धन नियमित रूप से निर्धनता में आते-जाते रहते हैं और कभी-कभी निर्धन अधिकांश समय संपन्न रहते हैं; दोनों अल्पकालिक निर्धन हैं।" },
  "s12eco-b-039": { stem: "ग्रामीण विकास की रणनीति के रूप में कृषि विविधीकरण से तात्पर्य है:", options: ["फसल प्रारूप में परिवर्तन तथा श्रमिकों का फसल खेती से संबद्ध क्रियाकलापों और गैर-कृषि क्षेत्रों की ओर स्थानांतरण", "एक ही उच्च उपज वाली फसल पर ध्यान केंद्रित करना", "केवल रासायनिक उर्वरकों का प्रयोग बढ़ाना", "बिखरी जोतों की चकबंदी"], explanation: "विविधीकरण केवल खेती पर निर्भरता का जोखिम घटाता है और पशुपालन, मत्स्यपालन, बागवानी तथा ग्रामीण गैर-कृषि कार्यों में उत्पादक रोजगार देता है।" },
  "s12eco-b-040": { stem: "श्रमिक-जनसंख्या अनुपात की गणना इस प्रकार की जाती है:", options: ["(बेरोजगार व्यक्ति ÷ श्रम बल) × 100", "(कुल श्रमिक ÷ कुल जनसंख्या) × 100", "(कुल श्रमिक ÷ श्रम बल) × 100", "(श्रम बल ÷ कार्यशील आयु जनसंख्या) × 100"], explanation: "श्रमिक-जनसंख्या अनुपात बताता है कि जनसंख्या का कितना प्रतिशत वास्तव में कार्यरत है। विकल्प A बेरोजगारी दर है।" },
  "s12eco-b-041": { stem: "'रोजगारहीन संवृद्धि' शब्द उस स्थिति को दर्शाता है जिसमें:", options: ["GDP स्थिर रहते हुए रोजगार बढ़ता है", "संवृद्धि केवल अनौपचारिक क्षेत्र तक सीमित रहती है", "उत्पादन और रोजगार दोनों घटते हैं", "GDP बढ़ता है पर रोजगार के अवसरों में तदनुरूप वृद्धि नहीं होती"], explanation: "रोजगारहीन संवृद्धि का अर्थ है कि उत्पादन (जैसे प्रौद्योगिकी या उत्पादकता वृद्धि से) बढ़ता है पर उसी अनुपात में नए रोजगार उत्पन्न नहीं होते।" },
  "s12eco-b-042": { stem: "निम्नलिखित में से कौन-सा सामाजिक आधारिक संरचना का उदाहरण है?", options: ["ऊर्जा (बिजली)", "परिवहन", "शिक्षा और स्वास्थ्य", "दूरसंचार"], explanation: "सामाजिक आधारिक संरचना (शिक्षा, स्वास्थ्य, आवास) मानव विकास में सहायक है। बिजली, परिवहन और संचार आर्थिक आधारिक संरचना हैं।" },
  "s12eco-b-043": { stem: "पर्यावरण की अपक्षय (जैसे अपशिष्ट और प्रदूषक) को आत्मसात करने की क्षमता कहलाती है:", options: ["धारण क्षमता", "अवशोषी क्षमता", "पुनर्जनन दर", "जैव विविधता सूचकांक"], explanation: "अवशोषी क्षमता पर्यावरण की अपक्षय को आत्मसात करने की योग्यता है। धारण क्षमता व्यापक शर्त है कि संसाधनों का निष्कर्षण पुनर्जनन से कम रहे और अपशिष्ट अवशोषी क्षमता के भीतर रहे।" },
  "s12eco-b-044": { stem: "एक शोधकर्ता अपने अध्ययन के लिए प्रकाशित जनगणना रिपोर्ट के आँकड़ों का प्रयोग करती है। उसके लिए ये आँकड़े हैं:", options: ["प्राथमिक आँकड़े", "द्वितीयक आँकड़े", "प्रायोगिक आँकड़े", "पायलट सर्वेक्षण आँकड़े"], explanation: "किसी अन्य संस्था द्वारा पहले से एकत्रित और संसाधित आँकड़े उपयोगकर्ता के लिए द्वितीयक आँकड़े हैं। जनगणना संगठन के लिए वे प्राथमिक आँकड़े थे।" },
  "s12eco-b-045": { stem: "कौन-सा कथन सरल यादृच्छिक प्रतिचयन का सही वर्णन करता है?", options: ["अन्वेषक उन इकाइयों को चुनता है जिन्हें वह समष्टि का प्रतिनिधि मानता है", "केवल सूची की पहली कुछ इकाइयाँ चुनी जाती हैं", "समष्टि की प्रत्येक इकाई के चुने जाने की समान संभावना होती है", "इकाइयाँ सबसे सुविधाजनक स्थानों से चुनी जाती हैं"], explanation: "यादृच्छिक प्रतिचयन में प्रत्येक व्यक्ति के चयन की समान संभावना होती है (जैसे लॉटरी या यादृच्छिक संख्या सारणी द्वारा)। विकल्प A सविचार (उद्देश्यपूर्ण) प्रतिचयन है।" },
  "s12eco-b-046": { stem: "प्रेक्षणों 7, 3, 9, 15, 11, 5 की माध्यिका है:", options: ["7", "8", "9", "8.33"], explanation: "क्रम में व्यवस्थित करने पर: 3, 5, 7, 9, 11, 15। 6 मानों की माध्यिका तीसरे और चौथे मान का माध्य है: (7 + 9)/2 = 8। 8.33 समांतर माध्य (50/6) है।" },
  "s12eco-b-047": { stem: "एक सामान्य रूप से विषम बंटन में माध्य 30 और माध्यिका 28 है। आनुभविक संबंध का प्रयोग करने पर बहुलक लगभग है:", options: ["24", "26", "32", "22"], explanation: "बहुलक = 3 माध्यिका − 2 माध्य = 3(28) − 2(30) = 84 − 60 = 24।" },
  "s12eco-b-048": { stem: "एक श्रेणी में सबसे बड़ा मान 50 और सबसे छोटा मान 10 है। परिसर गुणांक है:", options: ["40", "1.5", "0.8", "0.67"], explanation: "परिसर गुणांक = (L − S)/(L + S) = 40/60 ≈ 0.67। 40 स्वयं परिसर है, जो निरपेक्ष माप है।" },
  "s12eco-b-049": { stem: "कार्ल पियर्सन के सहसंबंध गुणांक का मान सदैव इनके बीच होता है:", options: ["0 और 1", "0 और ∞", "−1 और +1", "−∞ और +∞"], explanation: "r का मान −1 (पूर्ण ऋणात्मक) से +1 (पूर्ण धनात्मक) तक होता है, और 0 कोई रैखिक सहसंबंध न होने को दर्शाता है।" },
  "s12eco-b-050": { stem: "लास्पेयर के कीमत सूचकांक में कीमतों को भारित किया जाता है:", options: ["चालू वर्ष की मात्राओं से", "आधार और चालू वर्ष की मात्राओं के गुणोत्तर माध्य से", "सभी मदों को समान भार देकर", "आधार वर्ष की मात्राओं से"], explanation: "लास्पेयर सूचकांक = Σp₁q₀/Σp₀q₀ × 100, जिसमें आधार वर्ष की मात्राएँ प्रयुक्त होती हैं। पाशे सूचकांक चालू वर्ष की मात्राएँ प्रयोग करता है।" },
  "s12eco-p-001": { stem: "किसी वस्तु की कीमत ₹10 से बढ़कर ₹12 होने पर उसकी माँगी गई मात्रा 100 से घटकर 80 इकाई हो जाती है। चाप (मध्य बिंदु) विधि से माँग की कीमत लोच (निरपेक्ष मान) लगभग है:", options: ["1.00", "1.22", "0.82", "1.50"], explanation: "चाप लोच = (ΔQ/औसत Q) ÷ (ΔP/औसत P) = (20/90) ÷ (2/11) = 220/180 ≈ 1.22। प्रारंभिक मानों का प्रयोग करने पर (20/100)/(2/10) = 1.00 आता है।" },
  "s12eco-p-002": { stem: "किसी वस्तु का माँग फलन q = 20 − 2p है। p = 4 पर माँग की बिंदु कीमत लोच (निरपेक्ष मान) है:", options: ["1.5", "0.4", "0.67", "1"], explanation: "p = 4 पर q = 12। रैखिक माँग q = a − bp के लिए e = bp/q = (2 × 4)/12 = 2/3 ≈ 0.67। लोच 1 केवल मध्य बिंदु p = 5 पर होती है।" },
  "s12eco-p-003": { stem: "अभिकथन (A): पूर्ण प्रतिस्पर्धा में फर्में दीर्घकाल में केवल सामान्य लाभ अर्जित करती हैं।\nकारण (R): फर्मों का निर्बाध प्रवेश और निकास असामान्य लाभ और हानि को समाप्त कर देता है।", options: ["A और R दोनों सही हैं और R, A की सही व्याख्या है", "A और R दोनों सही हैं पर R, A की सही व्याख्या नहीं है", "A सही है पर R गलत है", "A गलत है पर R सही है"], explanation: "असामान्य लाभ नई फर्मों को आकर्षित करता है जिससे कीमत घटती है; हानि फर्मों को बाहर करती है जिससे कीमत बढ़ती है। यह प्रक्रिया तब रुकती है जब कीमत न्यूनतम LRAC के बराबर हो, अर्थात आर्थिक लाभ शून्य।" },
  "s12eco-p-004": { stem: "एक फर्म का उत्पादन फलन Q = 5L^0.6 K^0.5 है। यह उत्पादन फलन दर्शाता है:", options: ["पैमाने के स्थिर प्रतिफल", "पैमाने के ह्रासमान प्रतिफल", "पैमाने के वर्धमान प्रतिफल", "पैमाने के प्रतिफल जिन्हें घातांकों से निर्धारित नहीं किया जा सकता"], explanation: "दोनों आगतों को t गुना करने पर Q, t^(0.6 + 0.5) = t^1.1 गुना होता है। चूँकि 1.1 > 1, पैमाने के वर्धमान प्रतिफल हैं (यद्यपि प्रत्येक साधन अलग-अलग ह्रासमान सीमांत उत्पाद दर्शाता है)।" },
  "s12eco-p-005": { stem: "एक फर्म की कुल लागत अनुसूची है: Q = 0, TC = ₹30; Q = 1, TC = ₹50; Q = 2, TC = ₹65; Q = 3, TC = ₹90; Q = 4, TC = ₹125। तीसरी इकाई की सीमांत लागत और 3 इकाइयों पर औसत परिवर्ती लागत क्रमशः हैं:", options: ["₹30 और ₹20", "₹20 और ₹25", "₹25 और ₹30", "₹25 और ₹20"], explanation: "TFC = Q = 0 पर TC = ₹30। MC₃ = 90 − 65 = ₹25। 3 इकाइयों पर TVC = 90 − 30 = ₹60, अतः AVC = 60/3 = ₹20। ₹30 तो 3 इकाइयों पर AC है।" },
  "s12eco-p-006": { stem: "एक पूर्ण प्रतिस्पर्धी फर्म के संबंध में निम्नलिखित कथनों पर विचार कीजिए:\n1. इसका अल्पकालीन पूर्ति वक्र न्यूनतम AVC और उससे ऊपर SMC वक्र का बढ़ता भाग है।\n2. इसका दीर्घकालीन पूर्ति वक्र न्यूनतम LRAC और उससे ऊपर LRMC वक्र का बढ़ता भाग है।\n3. अल्पकाल में यह तब तक उत्पादन जारी रखती है जब तक कीमत न्यूनतम AFC को पूरा करती है।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?", options: ["केवल 1", "केवल 1 और 2", "केवल 2 और 3", "1, 2 और 3"], explanation: "अल्पकाल में उत्पादन बंद करने का बिंदु न्यूनतम AVC है (स्थिर लागतें अपरिहार्य हैं), और दीर्घकाल में फर्म को कीमत ≥ न्यूनतम LRAC चाहिए। कथन 3 गलत है: AFC पूरा होना उत्पादन बंद करने के निर्णय से असंबद्ध है।" },
  "s12eco-p-007": { stem: "लाभ अधिकतम करने वाले एक एकाधिकारी की चुने गए उत्पादन पर सीमांत लागत ₹20 है, और उस बिंदु पर माँग की कीमत लोच 2 है। वह जो कीमत लेता है, वह है:", options: ["₹40", "₹10", "₹30", "₹20"], explanation: "संतुलन पर MR = MC = 20, और MR = P(1 − 1/e) = P(1 − 1/2) = P/2। अतः P = ₹40। पूर्ण प्रतिस्पर्धा के विपरीत, कीमत MC से अधिक है।" },
  "s12eco-p-008": { stem: "एक एकाधिकारी का माँग वक्र P = 100 − 2Q है और उसकी स्थिर सीमांत लागत ₹20 है (कोई स्थिर लागत नहीं)। उसका लाभ अधिकतम करने वाला उत्पादन और कीमत हैं:", options: ["Q = 40, P = ₹20", "Q = 10, P = ₹80", "Q = 20, P = ₹20", "Q = 20, P = ₹60"], explanation: "TR = 100Q − 2Q², अतः MR = 100 − 4Q। MR = MC रखने पर: 100 − 4Q = 20, Q = 20, और P = 100 − 40 = ₹60। Q = 40, P = ₹20 प्रतिस्पर्धी (P = MC) परिणाम है।" },
  "s12eco-p-009": { stem: "सूची I (बाजार का रूप) को सूची II (विशेषता) से सुमेलित कीजिए:\nA. पूर्ण प्रतिस्पर्धा\nB. एकाधिकार\nC. एकाधिकारी प्रतिस्पर्धा\nD. अल्पाधिकार\n1. कुछ विक्रेता जिनके निर्णय परस्पर निर्भर हैं\n2. विभेदीकृत उत्पादों वाले अनेक विक्रेता\n3. समरूप उत्पाद के अनेक विक्रेता, प्रत्येक कीमत स्वीकारक\n4. ऐसे उत्पाद का एकल विक्रेता जिसका कोई निकट स्थानापन्न नहीं", options: ["A-3, B-4, C-1, D-2", "A-4, B-3, C-2, D-1", "A-3, B-4, C-2, D-1", "A-2, B-4, C-3, D-1"], explanation: "समरूप उत्पाद और कीमत स्वीकारिता पूर्ण प्रतिस्पर्धा की पहचान है; एकल विक्रेता एकाधिकार की; उत्पाद विभेदीकरण एकाधिकारी प्रतिस्पर्धा की; और कुछ फर्मों की परस्पर निर्भरता अल्पाधिकार की।" },
  "s12eco-p-010": { stem: "किसी वस्तु के माँग और पूर्ति फलन Qd = 200 − 5P और Qs = 50 + 10P हैं। यदि सरकार ₹8 की उच्चतम कीमत सीमा निर्धारित करती है, तो बाजार में होगी:", options: ["30 इकाइयों की अधिपूर्ति", "30 इकाइयों की अधिमाँग", "10 इकाइयों की अधिमाँग", "कोई प्रभाव नहीं, क्योंकि बाजार ₹8 पर संतुलित होता है"], explanation: "संतुलन: 200 − 5P = 50 + 10P से P = ₹10, Q = 150। ₹8 पर Qd = 160 और Qs = 130, अतः 30 इकाइयों की कमी (अधिमाँग) है।" },
  "s12eco-p-011": { stem: "एक उपभोक्ता का उपयोगिता फलन U = xy है। उसकी आय ₹120, x की कीमत ₹2 और y की कीमत ₹4 है। उसका उपयोगिता अधिकतम करने वाला बंडल है:", options: ["x = 15, y = 30", "x = 30, y = 15", "x = 20, y = 20", "x = 40, y = 10"], explanation: "MRS = MUx/MUy = y/x को Px/Py = 1/2 के बराबर होना चाहिए, अतः x = 2y। बजट: 2x + 4y = 120 से 8y = 120, y = 15, x = 30। अन्य विकल्प बजट रेखा पर हैं पर MRS = कीमत अनुपात को संतुष्ट नहीं करते।" },
  "s12eco-p-012": { stem: "अल्पकालीन उत्पाद वक्रों के संबंध में निम्नलिखित कथनों पर विचार कीजिए:\n1. जब MP, AP से ऊपर होता है, तो AP बढ़ता है।\n2. MP, AP को AP के अधिकतम बिंदु पर काटता है।\n3. जब TP घटती दर से बढ़ता है, तो MP ऋणात्मक होता है।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?", options: ["केवल 1 और 3", "केवल 2", "केवल 1 और 2", "1, 2 और 3"], explanation: "कथन 1 और 2 औसत-सीमांत संबंध से निकलते हैं। जब TP घटती दर से बढ़ता है तो MP घट रहा होता है पर धनात्मक रहता है; MP केवल तब ऋणात्मक होता है जब TP घटता है।" },
  "s12eco-p-013": { stem: "मूल बिंदु से गुजरने वाले सीधी रेखा के पूर्ति वक्र की पूर्ति की कीमत लोच होती है:", options: ["शून्य के बराबर", "इकाई से अधिक", "इकाई से कम", "प्रत्येक बिंदु पर इकाई के बराबर"], explanation: "q = bp के लिए es = (dq/dp)(p/q) = b × p/(bp) = 1 सभी बिंदुओं पर। कीमत अक्ष को काटने वाले रैखिक पूर्ति वक्र की es > 1 और मात्रा अक्ष को काटने वाले की es < 1 होती है।" },
  "s12eco-p-014": { stem: "अन्य बातें समान रहने पर, वस्तु X की कीमत 10% बढ़ने पर वस्तु Y की माँगी गई मात्रा 5% घट जाती है। तिर्यक कीमत लोच और X तथा Y का संबंध है:", options: ["−0.5; पूरक", "+0.5; स्थानापन्न", "−2; पूरक", "+2; स्थानापन्न"], explanation: "तिर्यक लोच = %ΔQy/%ΔPx = −5/10 = −0.5। ऋणात्मक चिह्न का अर्थ है कि एक की कीमत बढ़ने से दूसरी की माँग घटती है, अतः वे पूरक हैं।" },
  "s12eco-p-015": { stem: "एक बाजार में 50 समरूप फर्में हैं, प्रत्येक की पूर्ति P ≥ 10 के लिए q = P − 10 है (और इससे नीचे शून्य)। बाजार माँग Q = 1,000 − 50P है। संतुलन कीमत और मात्रा हैं:", options: ["P = ₹15, Q = 250", "P = ₹10, Q = 500", "P = ₹20, Q = 500", "P = ₹12.5, Q = 375"], explanation: "बाजार पूर्ति = 50(P − 10) = 50P − 500। 1,000 − 50P = 50P − 500 रखने पर P = ₹15 और Q = 250 (प्रत्येक फर्म 5 इकाई की पूर्ति करती है)।" },
  "s12eco-p-016": { stem: "10% वैधानिक आरक्षित अनुपात वाली बैंकिंग प्रणाली में ₹10,000 की प्राथमिक जमा की जाती है। नकदी रिसाव न मानने पर, प्रणाली अधिकतम कितने ऋण (साख) का सृजन कर सकती है?", options: ["₹1,00,000", "₹90,000", "₹10,000", "₹9,000"], explanation: "कुल जमाएँ = 10,000 × 1/0.1 = ₹1,00,000। इसका 10%, यानी ₹10,000, आरक्षित रहता है, अतः ऋण = 1,00,000 − 10,000 = ₹90,000।" },
  "s12eco-p-017": { stem: "एक अर्थव्यवस्था में सीमांत बचत प्रवृत्ति 0.25 है। यदि निवेश ₹500 करोड़ बढ़ता है, तो उपभोग व्यय में परिणामी वृद्धि है:", options: ["₹2,000 करोड़", "₹500 करोड़", "₹375 करोड़", "₹1,500 करोड़"], explanation: "k = 1/MPS = 4, अतः ΔY = 4 × 500 = ₹2,000 करोड़। ΔC = MPC × ΔY = 0.75 × 2,000 = ₹1,500 करोड़ (अथवा ΔY − ΔI)।" },
  "s12eco-p-018": { stem: "दो-क्षेत्रीय अर्थव्यवस्था में C = 50 + 0.8Y और स्वायत्त निवेश I = 150 (₹ करोड़) है। आय का संतुलन स्तर है:", options: ["₹1,000 करोड़", "₹250 करोड़", "₹800 करोड़", "₹2,000 करोड़"], explanation: "Y = C + I से Y = 50 + 0.8Y + 150, अतः 0.2Y = 200 और Y = ₹1,000 करोड़। जाँच: C = 850, और 850 + 150 = 1,000।" },
  "s12eco-p-019": { stem: "सरकारी लेखे (₹ करोड़): राजस्व प्राप्तियाँ 800, राजस्व व्यय 1,000, पूँजीगत व्यय 400, गैर-ऋण पूँजीगत प्राप्तियाँ 100, ब्याज भुगतान 150। राजकोषीय घाटा और प्राथमिक घाटा क्रमशः हैं:", options: ["₹600 और ₹450", "₹200 और ₹50", "₹500 और ₹350", "₹500 और ₹650"], explanation: "राजकोषीय घाटा = कुल व्यय (1,000 + 400) − (800 + 100) = ₹500 करोड़। प्राथमिक घाटा = 500 − 150 = ₹350 करोड़। ₹200 करोड़ राजस्व घाटा है।" },
  "s12eco-p-020": { stem: "अभिकथन (A): यदि सभी परिवार अपनी आय का बड़ा अनुपात बचाने का प्रयास करें, तो अर्थव्यवस्था में कुल बचत नहीं भी बढ़ सकती।\nकारण (R): सीमांत बचत प्रवृत्ति में वृद्धि गुणक और समग्र माँग को घटाती है, जिससे आय का संतुलन स्तर कम हो जाता है।", options: ["A और R दोनों सही हैं और R, A की सही व्याख्या है", "A और R दोनों सही हैं पर R, A की सही व्याख्या नहीं है", "A सही है पर R गलत है", "A गलत है पर R सही है"], explanation: "यह मितव्ययिता का विरोधाभास है: अधिक बचत का प्रयास उपभोग और आय घटाता है, अतः नए संतुलन पर बचत (= निवेश) अपरिवर्तित रह सकती है या घट भी सकती है।" },
  "s12eco-p-021": { stem: "आँकड़े (₹ करोड़): कर्मचारियों का पारिश्रमिक 800, किराया 100, ब्याज 150, लाभ 250, स्व-नियोजितों की मिश्रित आय 200, विदेशों से निवल साधन आय −30, स्थायी पूँजी का उपभोग 40, निवल अप्रत्यक्ष कर 60। बाजार कीमत पर GNP है:", options: ["₹1,500 करोड़", "₹1,570 करोड़", "₹1,630 करोड़", "₹1,470 करोड़"], explanation: "NDPfc = 800 + 100 + 150 + 250 + 200 = 1,500। GNPmp = NDPfc + NFIA + मूल्यह्रास + NIT = 1,500 − 30 + 40 + 60 = ₹1,570 करोड़। NFIA को +30 मानने पर ₹1,630 करोड़ आता है।" },
  "s12eco-p-022": { stem: "निम्नलिखित कथनों पर विचार कीजिए:\n1. नकद आरक्षित अनुपात में वृद्धि मुद्रा गुणक को घटाती है।\n2. रिवर्स रेपो दर वह दर है जिस पर RBI वाणिज्यिक बैंकों से उधार लेता है।\n3. वैधानिक तरलता अनुपात बैंकों को RBI के पास नकद जमा के रूप में रखना होता है।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?", options: ["केवल 1 और 2", "केवल 1", "केवल 2 और 3", "1, 2 और 3"], explanation: "अधिक CRR से बैंकों के पास उधार देने को कम बचता है, जिससे गुणक घटता है, और रिवर्स रेपो RBI की उधार दर है। SLR बैंक स्वयं सरकारी प्रतिभूतियों, नकदी और सोने जैसी तरल परिसंपत्तियों में रखते हैं; RBI के पास CRR रखा जाता है।" },
  "s12eco-p-023": { stem: "जनता का करेंसी-जमा अनुपात 0.2 और बैंकों का आरक्षित-जमा अनुपात 0.1 है। मुद्रा गुणक (M/H) है:", options: ["10", "3.33", "5", "4"], explanation: "मुद्रा गुणक = (1 + cdr)/(cdr + rdr) = 1.2/0.3 = 4। 10 (= 1/rdr) करेंसी रिसाव की उपेक्षा करता है, और 3.33 (= 1/0.3) अंश में 1 + cdr को छोड़ देता है।" },
  "s12eco-p-024": { stem: "किसी देश के भुगतान संतुलन में घाटे का अर्थ है कि:", options: ["दृश्य आयात दृश्य निर्यात से अधिक हैं", "BoP खातों में कुल नामे कुल जमा से अधिक हैं", "स्वायत्त भुगतान स्वायत्त प्राप्तियों से अधिक हैं, अतः आधिकारिक भंडार में कमी जैसे समायोजक लेन-देन आवश्यक हैं", "पूँजी खाता निवल बहिर्वाह दर्शाता है"], explanation: "BoP का घाटा या अधिशेष स्वायत्त लेन-देन के आधार पर आँका जाता है; अंतर भंडार में कमी जैसी समायोजक मदों से पूरा होता है। लेखांकन में कुल नामे सदैव कुल जमा के बराबर होते हैं, और विकल्प A केवल व्यापार घाटा है।" },
  "s12eco-p-025": { stem: "सूची I को सूची II से सुमेलित कीजिए:\nA. स्थिर विनिमय दर\nB. नम्य विनिमय दर\nC. प्रबंधित तिरती (मैनेज्ड फ्लोटिंग)\nD. अवमूल्यन\n1. बाजार शक्तियों द्वारा निर्धारित दर, केंद्रीय बैंक के सामयिक हस्तक्षेप के साथ\n2. स्थिर व्यवस्था में घरेलू मुद्रा के मूल्य में आधिकारिक कमी\n3. सरकार या केंद्रीय बैंक द्वारा निर्धारित (पेग की गई) दर\n4. केवल विदेशी मुद्रा की माँग और पूर्ति से निर्धारित दर", options: ["A-4, B-3, C-1, D-2", "A-3, B-4, C-1, D-2", "A-3, B-1, C-4, D-2", "A-2, B-4, C-1, D-3"], explanation: "स्थिर दरें आधिकारिक रूप से निर्धारित होती हैं (3), नम्य दरें बाजार से निर्धारित होती हैं (4), प्रबंधित तिरती में बाजार और हस्तक्षेप दोनों होते हैं (1), और अवमूल्यन स्थिर व्यवस्था में आधिकारिक कमी है (2)।" },
  "s12eco-p-026": { stem: "एक अर्थव्यवस्था में MPC 0.8 है। सरकार अपना व्यय ₹100 करोड़ बढ़ाती है और उसे पूर्णतः ₹100 करोड़ के एकमुश्त कर से वित्तपोषित करती है। संतुलन आय बढ़ेगी:", options: ["₹500 करोड़", "₹400 करोड़", "शून्य", "₹100 करोड़"], explanation: "G से ΔY = 100/(1 − 0.8) = 500; T से ΔY = −0.8 × 100/0.2 = −400। निवल वृद्धि = ₹100 करोड़: संतुलित बजट गुणक 1 है।" },
  "s12eco-p-027": { stem: "MPC = 0.75 होने पर, एकमुश्त करों में ₹100 करोड़ की कटौती संतुलन आय को बढ़ाएगी:", options: ["₹400 करोड़", "₹100 करोड़", "₹75 करोड़", "₹300 करोड़"], explanation: "कर गुणक = −MPC/(1 − MPC) = −0.75/0.25 = −3, अतः 100 की कर कटौती आय को ₹300 करोड़ बढ़ाती है। ₹400 करोड़ व्यय गुणक का प्रयोग है, जो G पर लागू होता है, T पर नहीं।" },
  "s12eco-p-028": { stem: "एक अर्थव्यवस्था पूर्ण रोजगार पर अधिमाँग (स्फीतिक अंतराल) का सामना कर रही है। निम्नलिखित में से कौन-सा उपयुक्त सुधारात्मक उपाय है?", options: ["रेपो दर घटाना", "सरकारी व्यय बढ़ाना", "CRR बढ़ाना और खुले बाजार में सरकारी प्रतिभूतियाँ बेचना", "ऋणों पर मार्जिन आवश्यकता घटाना"], explanation: "अधिमाँग के लिए मुद्रा पूर्ति और व्यय में संकुचन आवश्यक है। अधिक CRR और खुले बाजार में बिक्री बैंक साख घटाते हैं; अन्य विकल्प माँग को और बढ़ाएँगे।" },
  "s12eco-p-029": { stem: "निम्नलिखित में से कौन-सा भारत की घरेलू आय में सम्मिलित है?", options: ["लंदन स्थित भारतीय स्टेट बैंक की शाखा द्वारा अर्जित लाभ", "नई दिल्ली स्थित रूसी दूतावास में कार्यरत भारतीय निवासियों के वेतन", "वाशिंगटन स्थित भारतीय दूतावास द्वारा अपने कर्मचारियों को दिए गए वेतन", "दुबई की संपत्ति से एक भारतीय निवासी को प्राप्त किराया"], explanation: "विदेश स्थित भारतीय दूतावास भारत के घरेलू क्षेत्र का भाग हैं, जबकि भारत स्थित विदेशी दूतावास नहीं। विकल्प A, B और D विदेशों से साधन आय हैं: ये भारत की राष्ट्रीय आय का भाग हैं, घरेलू आय का नहीं।" },
  "s12eco-p-030": { stem: "उपभोग फलन C = 40 + 0.6Y के लिए Y = 200 पर औसत उपभोग प्रवृत्ति और सीमांत उपभोग प्रवृत्ति क्रमशः हैं:", options: ["0.8 और 0.6", "0.6 और 0.8", "0.2 और 0.6", "0.8 और 0.4"], explanation: "C = 40 + 120 = 160, अतः APC = 160/200 = 0.8। MPC ढाल है, 0.6। धनात्मक स्वायत्त उपभोग होने पर प्रत्येक धनात्मक आय पर APC, MPC से अधिक होती है।" },
  "s12eco-p-031": { stem: "स्वतंत्रता के बाद भारत में भूमि सुधारों के संबंध में निम्नलिखित कथनों पर विचार कीजिए:\n1. ज़मींदारों जैसे बिचौलियों का उन्मूलन किया गया।\n2. भूमि की अधिकतम सीमा (सीलिंग) कानून पूरे देश में सफलतापूर्वक लागू हुए।\n3. भूमि सुधार केरल और पश्चिम बंगाल में अधिक सफल रहे, जहाँ सरकारें 'जोतने वाले को भूमि' की नीति के प्रति प्रतिबद्ध थीं।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?", options: ["केवल 1 और 2", "केवल 1 और 3", "केवल 2 और 3", "1, 2 और 3"], explanation: "बिचौलियों के उन्मूलन से लगभग 200 लाख काश्तकार स्वामी बने, पर सीलिंग कानूनों में देरी हुई और बड़े भूस्वामियों ने कमियों और हस्तांतरण द्वारा उनसे बचाव किया। केरल और पश्चिम बंगाल उल्लेखनीय सफलताएँ थीं।" },
  "s12eco-p-032": { stem: "अभिकथन (A): आयात प्रतिस्थापन की नीति के अंतर्गत प्रशुल्क और कोटा ने भारतीय उद्योगों को विदेशी प्रतिस्पर्धा से संरक्षण दिया।\nकारण (R): ऐसे संरक्षण ने भारतीय उद्योगों को सदैव कुशल और अंतरराष्ट्रीय स्तर पर प्रतिस्पर्धी बनाया।", options: ["A और R दोनों सही हैं और R, A की सही व्याख्या है", "A और R दोनों सही हैं पर R, A की सही व्याख्या नहीं है", "A सही है पर R गलत है", "A गलत है पर R सही है"], explanation: "अंतर्मुखी व्यापार नीति में घरेलू फर्मों के संरक्षण हेतु प्रशुल्क और कोटा का प्रयोग हुआ। पर दीर्घकालीन संरक्षण ने गुणवत्ता सुधारने और लागत घटाने की प्रेरणा कम की, जिसे आलोचक अकुशलता का कारण मानते हैं।" },
  "s12eco-p-033": { stem: "1991 के सुधार उपाय (सूची I) को सुधार क्षेत्र (सूची II) से सुमेलित कीजिए:\nA. अधिकांश उद्योगों के लिए औद्योगिक लाइसेंस व्यवस्था की समाप्ति\nB. SLR और CRR में कमी\nC. आयात पर मात्रात्मक प्रतिबंधों की समाप्ति\nD. व्यक्तिगत आयकर दरों में कमी\n1. वित्तीय क्षेत्रक सुधार\n2. औद्योगिक क्षेत्रक का विनियमीकरण\n3. कर सुधार\n4. विदेशी व्यापार नीति सुधार", options: ["A-1, B-2, C-4, D-3", "A-2, B-1, C-4, D-3", "A-2, B-1, C-3, D-4", "A-4, B-1, C-2, D-3"], explanation: "लाइसेंस समाप्ति औद्योगिक विनियमीकरण है, आरक्षित अनुपात घटाने से बैंकों के कोष मुक्त हुए (वित्तीय सुधार), आयात कोटा हटाना व्यापार सुधार है, और आयकर दरें घटाना कर सुधार है।" },
  "s12eco-p-034": { stem: "NCERT भारत में निर्धनता निवारण के दृष्टिकोण के तीन आयामों का वर्णन करता है। सार्वजनिक वितरण प्रणाली, समेकित बाल विकास सेवाएँ और मध्याह्न भोजन योजना किस दृष्टिकोण से संबंधित हैं?", options: ["रिसाव (ट्रिकल-डाउन) संवृद्धि-उन्मुख दृष्टिकोण", "विशिष्ट स्वरोजगार और मजदूरी-रोजगार कार्यक्रम", "निर्धनों को न्यूनतम आधारभूत सुविधाएँ उपलब्ध कराना", "भूमि पुनर्वितरण दृष्टिकोण"], explanation: "ये योजनाएँ सार्वजनिक व्यय द्वारा आधारभूत सुविधाएँ देकर निर्धनों के भोजन और पोषण स्तर में सुधार करती हैं। संवृद्धि पहला दृष्टिकोण है और आय तथा रोजगार सृजन कार्यक्रम दूसरा।" },
  "s12eco-p-035": { stem: "कौन-सा कथन मानव पूँजी और मानव विकास में सही अंतर करता है?", options: ["दोनों शिक्षा और स्वास्थ्य को केवल श्रम उत्पादकता बढ़ाने का साधन मानते हैं", "मानव पूँजी शिक्षा और स्वास्थ्य को स्वयं में साध्य मानती है, जबकि मानव विकास उन्हें साधन मानता है", "मानव विकास स्वास्थ्य की उपेक्षा कर केवल शिक्षा पर विचार करता है", "मानव पूँजी शिक्षा और स्वास्थ्य को श्रम उत्पादकता बढ़ाने का साधन मानती है, जबकि मानव विकास उन्हें स्वयं में साध्य मानता है"], explanation: "मानव पूँजी लोगों में निवेश को उत्पादन में उसके प्रतिफल के कारण महत्त्व देती है। मानव विकास मानता है कि शिक्षा और स्वास्थ्य कल्याण के अभिन्न अंग हैं, चाहे वे उत्पादकता बढ़ाएँ या नहीं।" },
  "s12eco-p-036": { stem: "भारत में ग्रामीण साख के संबंध में निम्नलिखित कथनों पर विचार कीजिए:\n1. क्षेत्रीय ग्रामीण बैंक 1975 में स्थापित किए गए।\n2. NABARD की स्थापना 1982 में ग्रामीण क्षेत्र का वित्तपोषण करने वाली संस्थाओं की गतिविधियों के समन्वय हेतु शीर्ष संस्था के रूप में हुई।\n3. औपचारिक संस्थाओं के प्रसार के साथ साहूकार जैसे अनौपचारिक स्रोतों की ग्रामीण साख में कोई भूमिका नहीं रही।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?", options: ["केवल 1", "केवल 2", "केवल 1 और 2", "1, 2 और 3"], explanation: "RRB 1975 से और NABARD 1982 से हैं। कथन 3 गलत है: औपचारिक संस्थाओं ने अनौपचारिक ऋणदाताओं को पूरी तरह नहीं हटाया, जो अब भी ग्रामीण साख का एक भाग देते हैं।" },
  "s12eco-p-037": { stem: "रोजगार पर NCERT की परिभाषा के अनुसार, सभी सार्वजनिक क्षेत्र के प्रतिष्ठान औपचारिक क्षेत्र के प्रतिष्ठान हैं, और निजी क्षेत्र के प्रतिष्ठान तब औपचारिक हैं जब वे कम से कम इतने श्रमिक नियुक्त करते हैं:", options: ["10 भाड़े के श्रमिक", "5 भाड़े के श्रमिक", "20 भाड़े के श्रमिक", "50 भाड़े के श्रमिक"], explanation: "सार्वजनिक क्षेत्र की इकाइयाँ और 10 या अधिक भाड़े के श्रमिक नियुक्त करने वाली निजी इकाइयाँ औपचारिक (संगठित) क्षेत्र बनाती हैं; उनके श्रमिकों को सामाजिक सुरक्षा लाभ मिलते हैं और वे श्रमिक संघ बना सकते हैं।" },
  "s12eco-p-038": { stem: "निम्नलिखित में से कौन-सी शर्त धारणीय विकास के लिए हरमन डेली की शर्तों में सम्मिलित नहीं है?", options: ["नवीकरणीय संसाधनों का निष्कर्षण उनकी पुनर्जनन दर से अधिक दर पर नहीं होना चाहिए", "गैर-नवीकरणीय संसाधनों के ह्रास की दर नवीकरणीय विकल्पों के सृजन की दर से अधिक नहीं होनी चाहिए", "मानव जनसंख्या पर्यावरण की धारण क्षमता के भीतर सीमित रहनी चाहिए", "पर्यावरण को अपशिष्टों के निःशुल्क निपटान स्थल के रूप में प्रयोग कर संवृद्धि अधिकतम करनी चाहिए"], explanation: "डेली के नियमों में आगत-कुशल प्रौद्योगिकी और प्रदूषण से उत्पन्न अकुशलताओं का सुधार भी शामिल है। पर्यावरण को निःशुल्क निपटान स्थल मानना ठीक वही है जिसे धारणीयता अस्वीकार करती है।" },
  "s12eco-p-039": { stem: "निम्नलिखित में से किस समूह में केवल गैर-वाणिज्यिक ऊर्जा स्रोत हैं?", options: ["कोयला, पेट्रोलियम और बिजली", "जलावन लकड़ी, कृषि अपशिष्ट और सूखा गोबर", "प्राकृतिक गैस, जलावन लकड़ी और कोयला", "बिजली, सूखा गोबर और पेट्रोलियम"], explanation: "गैर-वाणिज्यिक स्रोत सामान्यतः खरीदे नहीं जाते बल्कि निःशुल्क एकत्र किए जाते हैं। कोयला, पेट्रोलियम, प्राकृतिक गैस और बिजली वाणिज्यिक स्रोत हैं।" },
  "s12eco-p-040": { stem: "भारत की 1991 से पूर्व की आर्थिक व्यवस्था की कौन-सी विशेषता 1991 की औद्योगिक नीति द्वारा बड़े पैमाने पर समाप्त की गई?", options: ["कुछ उद्योगों की छोटी सूची को छोड़कर सभी के लिए औद्योगिक लाइसेंस व्यवस्था", "केंद्रीय बैंक का संचालन", "पंचवर्षीय योजना", "रेलवे में सार्वजनिक क्षेत्र की उपस्थिति"], explanation: "1991 की नीति ने कुछ उद्योगों (जैसे खतरनाक या सामरिक) को छोड़कर लाइसेंस व्यवस्था समाप्त कर दी। पंचवर्षीय योजनाएँ 1991 के बाद भी जारी रहीं, और रेलवे सार्वजनिक क्षेत्र में ही रहा।" },
  "s12eco-p-041": { stem: "1950 से 1990 के बीच भारतीय कृषि के संबंध में निम्नलिखित कथनों पर विचार कीजिए:\n1. GDP में कृषि का अंश काफी घटा, पर कृषि पर निर्भर जनसंख्या का अनुपात उसी अनुपात में नहीं घटा।\n2. HYV फसलों पर कीटों के आक्रमण की संभावना अधिक थी, और सरकारी अनुसंधान संस्थानों की सेवाओं से छोटे किसानों का जोखिम घटा।\n3. हरित क्रांति से पहले मुख्यतः चावल उगाने वाले क्षेत्रों को लाभ हुआ।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?", options: ["केवल 1 और 2", "केवल 2", "केवल 1 और 3", "केवल 3"], explanation: "उत्पादन में अंश घटने के बावजूद कृषि पर श्रम बल की निर्भरता ऊँची रही, और सरकारी अनुसंधान सहायता से HYV कीट जोखिम घटा। प्रारंभिक लाभ मुख्यतः गेहूँ उगाने वाले क्षेत्रों को मिले, अतः कथन 3 गलत है।" },
  "s12eco-p-042": { stem: "1991 के बाद के उदारीकरण के अंतर्गत विदेशी मुद्रा विनियमन अधिनियम (FERA) को किससे प्रतिस्थापित किया गया?", options: ["प्रतिस्पर्धा अधिनियम, 2002", "SEBI अधिनियम, 1992", "कंपनी अधिनियम, 2013", "विदेशी मुद्रा प्रबंधन अधिनियम (FEMA), 1999"], explanation: "FEMA (1999) ने नियामक FERA के स्थान पर विदेशी मुद्रा के प्रबंधन का ढाँचा प्रस्तुत किया, जो उदारीकृत बाह्य क्षेत्र के अनुरूप था।" },
  "s12eco-p-043": { stem: "प्रेक्षणों 2, 4, 4, 4, 5, 5, 7, 9 का मानक विचलन है:", options: ["2", "4", "1.5", "2.5"], explanation: "माध्य = 40/8 = 5। विचलनों के वर्ग: 9, 1, 1, 1, 0, 0, 4, 16, जिनका योग 32 है। प्रसरण = 32/8 = 4, अतः SD = 2। 4 प्रसरण है।" },
  "s12eco-p-044": { stem: "श्रेणी A का माध्य 50 और मानक विचलन 10 है; श्रेणी B का माध्य 80 और मानक विचलन 12 है। कौन-सी श्रेणी अधिक संगत (स्थिर) है, और क्यों?", options: ["A, क्योंकि इसका विचरण गुणांक 20% है", "B, क्योंकि इसका विचरण गुणांक 15% है", "A, क्योंकि इसका मानक विचलन कम है", "दोनों समान रूप से संगत हैं"], explanation: "CV = SD/माध्य × 100: A = 20%, B = 15%। कम CV अधिक संगतता दर्शाता है। माध्य भिन्न होने पर केवल SD की तुलना भ्रामक है।" },
  "s12eco-p-045": { stem: "कोटि के 5 युग्मों के लिए कोटि अंतरों के वर्गों का योग Σd² = 10 है। स्पीयरमैन का कोटि सहसंबंध गुणांक है:", options: ["−0.5", "0.75", "0.5", "0.25"], explanation: "rs = 1 − 6Σd²/[n(n² − 1)] = 1 − 60/(5 × 24) = 1 − 0.5 = 0.5।" },
  "s12eco-p-046": { stem: "दो वस्तुएँ: A का आधार वर्ष मूल्य ₹2, आधार वर्ष मात्रा 10 और चालू मूल्य ₹3 है; B का आधार वर्ष मूल्य ₹5, आधार वर्ष मात्रा 4 और चालू मूल्य ₹6 है। चालू वर्ष के लिए लास्पेयर कीमत सूचकांक है:", options: ["120", "125", "150", "135"], explanation: "Σp₁q₀ = 3 × 10 + 6 × 4 = 54; Σp₀q₀ = 2 × 10 + 5 × 4 = 40। सूचकांक = 54/40 × 100 = 135।" },
  "s12eco-p-047": { stem: "निम्नलिखित कथनों पर विचार कीजिए:\n1. प्रेक्षणों के उनके समांतर माध्य से विचलनों का योग शून्य होता है।\n2. विचलनों के वर्गों का योग तब न्यूनतम होता है जब विचलन माध्यिका से लिए जाएँ।\n3. माध्यिका पर चरम मानों का प्रभाव समांतर माध्य की अपेक्षा कम होता है।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?", options: ["केवल 1 और 2", "केवल 1 और 3", "केवल 2 और 3", "1, 2 और 3"], explanation: "विचलनों के वर्गों का योग माध्य के सापेक्ष न्यूनतम होता है; माध्यिका के सापेक्ष निरपेक्ष विचलनों का योग न्यूनतम होता है। कथन 1 और 3 मानक गुण हैं।" },
  "s12eco-p-048": { stem: "X और Y के बीच सहसंबंध गुणांक 0.6 है। यदि U = (X − 10)/2 और V = (Y − 5)/3, तो U और V के बीच सहसंबंध गुणांक है:", options: ["0.6", "0.1", "0.9", "0.4"], explanation: "r मूल बिंदु और पैमाने के परिवर्तन से स्वतंत्र है (जब पैमाने के गुणकों का चिह्न समान हो), अतः r(U, V) = 0.6।" },
  "s12eco-p-049": { stem: "एक बंटन का प्रथम चतुर्थक 20 और तृतीय चतुर्थक 40 है। चतुर्थक विचलन और चतुर्थक विचलन गुणांक क्रमशः हैं:", options: ["20 और 0.33", "10 और 0.5", "10 और 0.33", "20 और 0.5"], explanation: "QD = (Q₃ − Q₁)/2 = 10। चतुर्थक विचलन गुणांक = (Q₃ − Q₁)/(Q₃ + Q₁) = 20/60 ≈ 0.33। 20 अंतर-चतुर्थक परिसर है।" },
  "s12eco-p-050": { stem: "किसी वर्ष-युग्म के लिए लास्पेयर कीमत सूचकांक 144 और पाशे कीमत सूचकांक 100 है। फिशर का आदर्श सूचकांक है:", options: ["122", "144", "100", "120"], explanation: "फिशर सूचकांक दोनों का गुणोत्तर माध्य है: √(144 × 100) = 12 × 10 = 120। 122 समांतर माध्य है।" },
};
